import { NextResponse } from "next/server";

const ipRequests = {};

export function middleware(req) {
  const ip = req.ip ?? "unknown";

  ipRequests[ip] = ipRequests[ip] || [];
  ipRequests[ip].push(Date.now());

  // Garde que les 30 dernières secondes
  ipRequests[ip] = ipRequests[ip].filter(time => time > Date.now() - 30000);

  // plus de 30 requêtes en 30 secondes = blocage
  if (ipRequests[ip].length > 30) {
    return new NextResponse("Too many requests", { status: 429 });
  }

  return NextResponse.next();
}
